const mongoose = require("mongoose");
const { runPaged } = require("../../../utils/helpers/pagination");

/**
 * PastDateRequest Mongoose Schema
 * Contains ONLY the required fields:
 * - _id (Native ObjectId auto-generated by MongoDB)
 * - branchId (Native ObjectId or null if appliesToAllBranches=true)
 * - appliesToAllBranches (Boolean)
 * - requestedBy (String, User ID or Name)
 * - requestedDate (String, e.g. "2025-09-01 09:00:00")
 * - requestedDateAt (ISODate)
 * - status (String, "Pending" | "Approved" | "Rejected")
 * - type (String, e.g. "Manual Admin Grant")
 * - createdAt (ISODate)
 * - updatedAt (ISODate or null)
 */
const pastDateRequestSchema = new mongoose.Schema(
  {
    branchId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Branch",
      default: null,
      index: true,
    },
    requestedBranch: {
      type: String,
      default: null,
      trim: true,
    },
    appliesToAllBranches: {
      type: Boolean,
      default: false,
    },
    requestedBy: {
      type: String,
      required: [true, "Requested by is required"],
      trim: true,
    },
    requestedDate: {
      type: String,
      required: [true, "Requested date is required"],
      trim: true,
      index: true,
    },
    requestedDateAt: {
      type: Date,
      default: function () {
        return this.requestedDate ? new Date(this.requestedDate) : new Date();
      },
    },
    status: {
      type: String,
      enum: ["Pending", "Approved", "Rejected"],
      default: "Pending",
      index: true,
    },
    type: {
      type: String,
      default: "Manual Admin Grant",
      trim: true,
    },
    createdAt: {
      type: Date,
      default: Date.now,
    },
    updatedAt: {
      type: Date,
      default: null,
    },
  },
  {
    versionKey: false,
    strict: true,
    toJSON: {
      virtuals: false,
      transform: (doc, ret) => {
        return {
          _id: ret._id,
          branchId: ret.branchId || null,
          requestedBranch: ret.requestedBranch || null,
          branchName: ret.branchName || ret.requestedBranch || null,
          appliesToAllBranches: Boolean(ret.appliesToAllBranches),
          requestedBy: ret.requestedBy,
          requestedDate: ret.requestedDate,
          requestedDateAt: ret.requestedDateAt,
          status: ret.status,
          type: ret.type,
          createdAt: ret.createdAt,
          updatedAt: ret.updatedAt || null,
        };
      },
    },
  }
);

pastDateRequestSchema.index({ branchId: 1, requestedDate: 1 });
pastDateRequestSchema.index({ status: 1, requestedDate: 1 });


const escapeRegex = (text) => String(text).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

/**
 * List requests. Optional filters (all combine):
 *   branchId, date           exact match
 *   status                   Pending | Approved | Rejected ("Pending" also matches a request saved without a status)
 *   requestedBranch          branch name, exact, ignoring case
 *   search                   text found in requested by, branch, date, status or type
 *   sort=requestedDate       newest requested date first (default is newest created first)
 *   page, limit              optional paging, see utils/helpers/pagination.js
 */
pastDateRequestSchema.statics.findAll = async function (filters = {}) {
  const query = {};
  const and = [];
  if (filters.branchId) query.branchId = filters.branchId;
  if (filters.status) {
    if (String(filters.status).toLowerCase() === "pending") {
      and.push({ $or: [{ status: /^pending$/i }, { status: null }] });
    } else {
      query.status = filters.status;
    }
  }
  if (filters.date) query.targetDate = filters.date;
  if (filters.requestedBranch && String(filters.requestedBranch).trim()) {
    query.requestedBranch = new RegExp(`^${escapeRegex(String(filters.requestedBranch).trim())}$`, "i");
  }
  const search = String(filters.search || "").trim();
  if (search) {
    const pattern = new RegExp(escapeRegex(search), "i");
    const anyOf = [{ requestedBy: pattern }, { requestedBranch: pattern }, { requestedDate: pattern }, { status: pattern }, { type: pattern }];
    // A request without a status is shown as Pending, so searching "pend" should find it too
    if ("pending".includes(search.toLowerCase())) anyOf.push({ status: null });
    and.push({ $or: anyOf });
  }
  if (and.length) query.$and = and;

  // _id breaks ties so a record never appears on two pages
  const sort = filters.sort === "requestedDate" ? { requestedDate: -1, _id: -1 } : { createdAt: -1, _id: -1 };
  return runPaged(
    () => this.find(query).sort(sort),
    () => this.countDocuments(query),
    filters
  );
};

pastDateRequestSchema.statics.update = async function (id, updateData) {
  return this.findByIdAndUpdate(id, { $set: updateData }, { new: true });
};

pastDateRequestSchema.statics.delete = async function (id) {
  return this.findByIdAndDelete(id);
};

const PastDateRequest = mongoose.model("PastDateRequest", pastDateRequestSchema, "pastDateRequests");

if (typeof pastDateRequestSchema !== "undefined" && typeof PastDateRequest !== "undefined" && pastDateRequestSchema.statics) {
  Object.assign(PastDateRequest, pastDateRequestSchema.statics);
}

module.exports = PastDateRequest;
